headerButton.customFunction:
// Grab the actual <button> element and disable it
// so the user can't spam-click while the command is in flight
let button = $event.target.closest('button');
if (button) {
    button.disabled = true;
}

const requestBody = {
    userName: widgetContext.currentUser.sub,
    status: "running",
    chargingCurrentSetpointA: 10
};

widgetContext.controlApi.sendOneWayCommand(
    "requestChargingSession",
    requestBody,
    5000
).subscribe({
    next: () => {
        // fired once TB has queued/delivered the RPC
        widgetContext.showSuccessToast(
    "Charging is started, please wait…",
    4000,          // duration in ms
    'top',         // verticalPosition
    'center'       // horizontalPosition
);
    },
    error: (err) => {
        widgetContext.showErrorToast("Command failed: " + JSON.stringify(err), 5000, 'bottom', 'center');
        if (button) button.disabled = false;
    },
    complete: () => {
        if (button) button.disabled = false;
    }
});

