dataKeys.postFuncBody:
if (value === null || value === undefined || value === "") {
    return "Charger available";
}

var evStatus;
try {
    evStatus = JSON.parse(value).status;
} catch (e) {
    return "Charger available";
}

if (typeof evStatus === 'undefined') {
    return "Charger available";
}

switch (evStatus) {
    case "running":
        return "Charging";
    case "paused":
        return "Charging paused";
    case "finished":
        return "Charging finished";
    case "scheduled":
        return "Charging scheduled";
    default:
        // fallback: capitalize whatever unknown status comes in
        return evStatus.charAt(0).toUpperCase() + evStatus.slice(1);
}

